import scala.collection.mutable.HashMap

def areAnagrams(firstText: String, secondText: String): Boolean = {
  if (firstText.length != secondText.length) {
    return false
  }

  val countByCharacter = HashMap.empty[Char, Int]

  for (character <- firstText) {
    countByCharacter(character) = countByCharacter.getOrElse(character, 0) + 1
  }

  for (character <- secondText) {
    val updatedCount = countByCharacter.getOrElse(character, 0) - 1
    if (updatedCount < 0) {
      return false
    }
    countByCharacter(character) = updatedCount
  }

  true
}

