import scala.collection.mutable.HashSet
import scala.collection.mutable.Queue

def shortestDistance(grid: Array[Array[Int]], startRow: Int, startColumn: Int, targetRow: Int, targetColumn: Int): Int = {
  val rowCount = grid.length
  val columnCount = grid(0).length
  val directions = Array((-1, 0), (1, 0), (0, -1), (0, 1))

  val pending = Queue((startRow, startColumn, 0))
  val visited = HashSet((startRow, startColumn))

  while (pending.nonEmpty) {
    val (currentRow, currentColumn, currentDistance) = pending.dequeue()

    if (currentRow == targetRow && currentColumn == targetColumn) {
      return currentDistance
    }

    for ((rowChange, columnChange) <- directions) {
      val neighbourRow = currentRow + rowChange
      val neighbourColumn = currentColumn + columnChange
      val neighbour = (neighbourRow, neighbourColumn)

      val isInside = neighbourRow >= 0 && neighbourRow < rowCount && neighbourColumn >= 0 && neighbourColumn < columnCount
      if (isInside && grid(neighbourRow)(neighbourColumn) == 0 && !visited.contains(neighbour)) {
        visited += neighbour
        pending.enqueue((neighbourRow, neighbourColumn, currentDistance + 1))
      }
    }
  }

  -1
}

