def binarySearch(sortedNumbers: Array[Int], target: Int): Int = {
  var leftIndex = 0
  var rightIndex = sortedNumbers.length - 1

  while (leftIndex <= rightIndex) {
    val middleIndex = leftIndex + (rightIndex - leftIndex) / 2
    val middleNumber = sortedNumbers(middleIndex)

    if (middleNumber == target) {
      return middleIndex
    } else if (middleNumber < target) {
      leftIndex = middleIndex + 1
    } else {
      rightIndex = middleIndex - 1
    }
  }

  -1
}

