def mostFrequentCharacter(text: String): Char = {
  val countByCharacter = HashMap.empty[Char, Int]

  for (character <- text) {
    countByCharacter(character) = countByCharacter.getOrElse(character, 0) + 1
  }

  countByCharacter.maxBy(entry => entry._2)._1
}

def countSetBits(number: Int): Int = {
  var remainingNumber = number
  var bitCount = 0

  while (remainingNumber != 0) {
    remainingNumber &= (remainingNumber - 1)
    // Version plus lisible mais souvent plus longue : tester chaque bit avec un masque.
    bitCount += 1
  }

  bitCount
}

