import scala.collection.mutable.HashSet

def isHappy(number: Int): Boolean = {
  var currentNumber = number
  val seenNumbers = HashSet.empty[Int]

  while (currentNumber != 1 && !seenNumbers.contains(currentNumber)) {
    seenNumbers += currentNumber

    var remainingNumber = currentNumber
    var nextNumber = 0

    while (remainingNumber > 0) {
      val lastDigit = remainingNumber % 10
      nextNumber += lastDigit * lastDigit
      remainingNumber /= 10
    }

    currentNumber = nextNumber
  }

  currentNumber == 1
}

