import scala.collection.mutable.HashSet

def countIslands(grid: Array[Array[Int]]): Int = {
  val rowCount = grid.length
  val columnCount = grid(0).length
  val visited = HashSet.empty[(Int, Int)]
  val directions = Array((-1, 0), (1, 0), (0, -1), (0, 1))

  def visitRegion(currentRow: Int, currentColumn: Int): Unit = {
    val isInside = currentRow >= 0 && currentRow < rowCount && currentColumn >= 0 && currentColumn < columnCount
    if (!isInside || grid(currentRow)(currentColumn) == 0 || visited.contains((currentRow, currentColumn))) {
      return
    }

    visited += ((currentRow, currentColumn))

    for ((rowChange, columnChange) <- directions) {
      visitRegion(currentRow + rowChange, currentColumn + columnChange)
    }
  }

  var islandCount = 0
  for (rowIndex <- 0 until rowCount; columnIndex <- 0 until columnCount) {
    if (grid(rowIndex)(columnIndex) == 1 && !visited.contains((rowIndex, columnIndex))) {
      islandCount += 1
      visitRegion(rowIndex, columnIndex)
    }
  }

  islandCount
}

