def maximumFixedWindowSum(numbers: Array[Int], windowSize: Int): Int = {
  var currentWindowSum = 0

  for (currentIndex <- 0 until windowSize) {
    currentWindowSum += numbers(currentIndex)
  }

  var maximumWindowSum = currentWindowSum

  for (rightIndex <- windowSize until numbers.length) {
    val enteringNumber = numbers(rightIndex)
    val leavingNumber = numbers(rightIndex - windowSize)

    currentWindowSum += enteringNumber
    currentWindowSum -= leavingNumber
    maximumWindowSum = math.max(maximumWindowSum, currentWindowSum)
  }

  maximumWindowSum
}
